/** The MapLibre source of a layer */
export const rasterSource = ({ tiles, tileSize, minzoom, maxzoom, bounds, attribution }: MapLayer) =>
  ({
    type: 'raster',
    tiles,
    tileSize: tileSize ?? 256,
    maxzoom,
    attribution,
    ...(minzoom === undefined ? {} : { minzoom }),
    ...(bounds ? { bounds } : {}),
  }) as RasterSourceSpecification;
